CREATE TABLE commerce_projections(id uuid PRIMARY KEY,tenant_id text NOT NULL,company_id text NOT NULL,product_id text NOT NULL,slug text NOT NULL,payload jsonb NOT NULL,publication_status text NOT NULL,version integer NOT NULL,updated_at timestamptz NOT NULL,UNIQUE(tenant_id,company_id,slug),UNIQUE(tenant_id,company_id,product_id));
CREATE TABLE commerce_orders(id uuid PRIMARY KEY,public_id text NOT NULL,tenant_id text NOT NULL,company_id text NOT NULL,channel text NOT NULL CHECK(channel='WEB'),status text NOT NULL,payment_status text NOT NULL,idempotency_key text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,UNIQUE(tenant_id,company_id,idempotency_key),UNIQUE(tenant_id,company_id,public_id));
CREATE TABLE commerce_reservations(id uuid PRIMARY KEY,tenant_id text NOT NULL,company_id text NOT NULL,product_id text NOT NULL,order_id uuid NOT NULL REFERENCES commerce_orders(id),quantity integer NOT NULL CHECK(quantity>0),status text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL);
CREATE INDEX commerce_projection_public ON commerce_projections(company_id,publication_status,updated_at DESC);CREATE INDEX commerce_reservation_stock ON commerce_reservations(company_id,product_id,status,expires_at);CREATE INDEX commerce_order_status ON commerce_orders(company_id,status,created_at DESC);
ALTER TABLE commerce_projections ENABLE ROW LEVEL SECURITY;ALTER TABLE commerce_projections FORCE ROW LEVEL SECURITY;ALTER TABLE commerce_orders ENABLE ROW LEVEL SECURITY;ALTER TABLE commerce_orders FORCE ROW LEVEL SECURITY;ALTER TABLE commerce_reservations ENABLE ROW LEVEL SECURITY;ALTER TABLE commerce_reservations FORCE ROW LEVEL SECURITY;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['commerce_projections','commerce_orders','commerce_reservations'] LOOP EXECUTE format('CREATE POLICY tenant_company_isolation ON %I USING(current_setting(''laex.platform_access'',true)=''on'' OR (tenant_id=current_setting(''laex.tenant_id'',true) AND company_id=current_setting(''laex.company_id'',true))) WITH CHECK(current_setting(''laex.platform_access'',true)=''on'' OR (tenant_id=current_setting(''laex.tenant_id'',true) AND company_id=current_setting(''laex.company_id'',true)))',t);END LOOP;END $$;
